received = {}          # 상대 기관 쪽: 주문 번호 → 접수 번호

def counterparty(order_id, deliver_reply):
    if order_id not in received:
        received[order_id] = f"ACK-{len(received) + 1}"
    return received[order_id] if deliver_reply else None   # None = 응답이 오다 끊김

delays = [1, 2, 4, 8]  # 분, 지수로 늘린다
for attempt, ok in enumerate([False, False, True]):
    r = counterparty("TOSS-0001", ok)
    print(f"{attempt + 1}번째 보냄 → 응답 {r}" + ("" if r else f", {delays[attempt]}분 뒤 다시"))
print("상대가 만든 주문 수:", len(received))
